// El objetivo es el mes SIGUIENTE al actual: la malla que se acaba de
// cargar en SERPI es la del mes entrante, y auditarla antes de que empiece
// es lo que permite corregir a tiempo.
const hoy = new Date();
const inicio = new Date(Date.UTC(hoy.getUTCFullYear(), hoy.getUTCMonth() + 1, 1));
const fin = new Date(Date.UTC(hoy.getUTCFullYear(), hoy.getUTCMonth() + 2, 0));

const iso = (d) => d.toISOString().slice(0, 10);
const periodo = iso(inicio).slice(0, 7);

return [{
  json: {
    periodo,
    desde: iso(inicio),
    hasta: iso(fin),
    archivo: 'RepProgramacion.xlsx',
  },
}];

const d = $input.first().json;
const esc = (s) => String(s ?? '').replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));

// Agrupado por cliente/puesto, NO por severidad: en SERPI se navega
// cliente -> puesto, asi que cada bloque es una sola visita en la que se
// corrige todo lo de ese puesto de una pasada.
const grupos = new Map();
for (const a of d.programador) {
  const clave = `${a.cliente_principal || '(sin cliente)'} &rsaquo; ${a.puesto_principal || '(sin puesto)'}`;
  if (!grupos.has(clave)) grupos.set(clave, []);
  grupos.get(clave).push(a);
}
const ordenados = [...grupos.entries()].sort((x, y) => y[1].length - x[1].length);

const bloques = ordenados.map(([clave, filas]) => `
<h4 style="margin:18px 0 4px;background:#eef2f7;padding:8px 10px;border-radius:6px;font-size:14px">
  ${esc(clave)} <span style="float:right;color:#5b6b7c;font-weight:normal">${filas.length} hallazgo${filas.length === 1 ? '' : 's'}</span>
</h4>
<table width="100%" cellspacing="0" style="border-collapse:collapse;font-size:13px">
${filas.map(a => `<tr>
  <td style="padding:6px 10px;border-bottom:1px solid #eef2f7;white-space:nowrap">
    <span style="background:${a.severidad === 'CRITICA' ? '#fee2e2;color:#b91c1c' : '#fef3c7;color:#b45309'};padding:2px 7px;border-radius:20px;font-size:11px;font-weight:700">${a.severidad}</span></td>
  <td style="padding:6px 10px;border-bottom:1px solid #eef2f7">${esc(a.guarda_nombre)}<br><span style="color:#5b6b7c;font-size:12px">${esc(a.guarda_cedula)} &middot; ${esc(a.fecha_referencia)}</span></td>
  <td style="padding:6px 10px;border-bottom:1px solid #eef2f7;color:#5b6b7c">${esc(a.detalle)}</td>
</tr>`).join('')}
</table>`).join('');

const criticas = d.programador.filter(a => a.severidad === 'CRITICA').length;

const html = `<div style="font-family:Segoe UI,Arial,sans-serif;color:#16202c;max-width:820px">
<h2 style="margin:0 0 4px">Correcciones pendientes en la malla &mdash; ${d.periodo}</h2>
<p style="color:#5b6b7c;margin:0 0 14px">${d.programador.length} hallazgos que se corrigen moviendo un turno${criticas ? `, de los cuales <b style="color:#b91c1c">${criticas} son cruces de horario</b> (el guarda esta asignado en dos sitios a la vez)` : ''}.</p>
<p style="background:#dbeafe;color:#1d4ed8;padding:10px 14px;border-radius:8px;font-size:13px">Estan agrupados por puesto: entra una sola vez a cada puesto en SERPI y corrige todo lo suyo de una pasada.</p>
${bloques}
<p style="margin-top:22px"><a href="${$vars.URL_DASHBOARD}" style="background:#1d4ed8;color:#fff;padding:10px 18px;border-radius:7px;text-decoration:none">Abrir el dashboard</a></p>
<p style="color:#5b6b7c;font-size:12px">No tienes que marcar nada como resuelto: corrige en SERPI y el proximo cargue de la malla lo confirma solo.</p>
</div>`;

return [{ json: { asunto: `Malla ${d.periodo}: ${d.programador.length} correcciones pendientes${criticas ? ` (${criticas} criticas)` : ''}`, html } }];
